using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CrypticHourglassCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/CrypticHourglassCustomDescription", order = 0)]
public class CrypticHourglassCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		CrypticHourglassAction crypticHourglassAction = battleAction as CrypticHourglassAction;
		string arg = crypticHourglassAction.HourglassMasteryAction.GetActionDescription(GetFinalAmountWithoutEquation(amountModified)).LowercaseFirst();
		string arg2 = crypticHourglassAction.SandsOfTimeAction.GetActionDescription(crypticHourglassAction.SandsOfTimeAmount).LowercaseFirst();
		return Smart.Format(GetRawLocalizedDescription(battleAction), arg, arg2);
	}
}
